      '@media (max-width:699px){',
      '  .modal-sheet:has(.vp-pr){overflow:hidden !important;display:flex;flex-direction:column;',
      '  padding:max(10px,env(safe-area-inset-top)) 16px calc(10px + env(safe-area-inset-bottom)) !important;}',
