      'margin-top:clamp(1px,.25vh,3px);}',

      /* ---- "Ver más beneficios ›" (debajo de la última tarjeta) ---- */
      '.vp-pr-mas{flex:none;display:flex;align-items:center;justify-content:center;gap:2px;width:100%;border:none;',
