      '@media (max-width:699px){',
      '  .vp-pr-v2 .vp-pr-h1{font-size:clamp(18px,2.2vh + 1.3vw,28px);margin:clamp(2px,.6vh,8px) 0 clamp(8px,1.5vh,16px);}',
